SELECT 'LIGHT_GROUP' AS type, '灯组引用' AS typeText, g.zone_id AS zoneId, z.zone_name AS zoneName, g.group_code AS refNo, CONCAT('分区[', z.zone_name, ']下仍登记灯组[', g.group_code, ']，请先将灯组划转至其他分区') AS detail FROM light_group g LEFT JOIN garage_zone z ON z.id = g.zone_id WHERE g.zone_id IN
#{zoneId}
ORDER BY g.zone_id ASC, g.group_code ASC LIMIT #{limit}
